insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intake-mk7','cxca','intake-mk7','Aftermarket intake install','Engine','air intake',array['intake','cold air intake','cai','ie intake','034 intake','x34','cts intake','racingline r600','turbo inlet pipe','tip']::text[],true,'1–1.5 hr',2) on conflict (id) do update set title=excluded.title, aliases=excluded.aliases, live=true, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('intake-mk7',$j${"id": "intake-mk7", "title": "Aftermarket intake install", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "intake-mk7-hero", "alsoFits": "MQB Gen 3 1.8T/2.0T: Golf, Golf R, A3/S3 8V (kits list them together; Golf R and S3 get an SAI block-off instead of the adapter)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "Two architectures. Full kits replace the airbox with a heat shield, cone filter and pipe; 034's X34/P34 keeps the factory lower box and replaces the lid and inlet.", "brandSpecific": true, "options": [{"id": "ie", "label": "Integrated Engineering V2 (full kit)", "when": "Heat shield, 5\" cone, inlet pipe; reroutes a coolant line. Full PDF.", "brand": true}, {"id": "o34", "label": "034Motorsport X34 / P34 (factory lower box)", "when": "Carbon or plastic upper on the stock lower box; baffle removed. Full PDF.", "brand": true}, {"id": "cts", "label": "CTS Turbo IT-270 (full kit)", "when": "Heat shield and pipe; brief sheet.", "brand": true}, {"id": "other", "label": "Other full kit (Racingline R600, APR, Unitronic, Eventuri)", "when": "Same shape as the IE path; follow the kit sheet.", "brand": false}]}, "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$350–800 · carbon lids and R600-class kits more", "risk": "Some kits open the cooling system · plastic grommet brackets snap · SAI fitting must be kept", "why": "On a stock IS20 turbo an intake is sound and throttle feel; on a tuned or IS38 car the restriction at the factory box and the turbo inlet pipe is real, and the intake is where the aftermarket starts. Three kits have complete public install guides, which is why this guide can be specific.", "note": "IE's and 034's PDFs are the references; CTS has a sheet. Owners report about an hour."}, "heroCap": "Schematic of a full-replacement kit: heat-shielded cone filter where the airbox was, pipe and silicone coupler to the turbo inlet, SAI fitting and vacuum line kept, and (IE) the factory coolant line that ran through the airbox area rerouted in silicone.", "lifespan": {"title": "When owners do this", "headline": ["First or second mod; before or with a Stage 1 tune"], "earliest": null, "detail": "Nothing wears out. Tuned and IS38 cars benefit most, and IS38 owners pair the intake with a larger turbo inlet pipe because the factory inlet is the next restriction.", "factors": ["Tune", "IS38 swap planned", "Want the turbo noise"], "inspect": ["Cone filter every oil change; clean per the maker"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus; FCP Gen 3 guide."}}, "should": {"yesIf": ["Tuned, or planning to be", "IS38 swap planned (do the inlet pipe too)", "Want induction and turbo noise"], "codes": [], "notes": ["Secondary air injection: US GTIs have an SAI line into the airbox. Every real kit provides an adapter (GTI, Golf, A3) or a block-off (Golf R, S3). Leave it open and you'll have a code and an unmetered leak.", {"text": "IE V2 removes a factory coolant line that runs across the airbox area and replaces it with a silicone hose. That means coolant loss, a cold engine, and the two included silicone caps used quickly. It's a two-minute step with a mess if you rush it.", "only": ["ie"]}, {"text": "034 keeps the factory lower airbox and its two rubber grommet posts; you remove the internal baffle (tight; wiggle it) and fit their upper. Least invasive of the full-featured kits.", "only": ["o34"]}, {"text": "CTS IT-270 is a full-replacement kit like IE's; follow the sheet's clamp order and check whether your revision touches the coolant line.", "only": ["cts"]}, {"text": "Racingline R600 and APR use a larger MAF housing and expect their own tune calibration; check with your tuner before buying. Eventuri is the premium carbon option.", "only": ["other"]}, "Turbo inlet pipe: not required, but the natural companion. IE's and 034's TIPs bolt to the turbo with one M8 (9 Nm per 034) and need coil 1 out for room (IE). Both intake kits ship the coupler for it."], "confidence": {"level": "high", "n": 3, "note": "Two complete manufacturer PDFs plus a sheet; SAI and coolant details straight from them."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "the kit you chose above", "note": "Shield/upper, filter, pipe, couplers, clamps, SAI adapter, vacuum fitting", "price": "$350–800", "links": []}, {"tier": "oe", "name": "Coolant, G13, for the top-up", "pn": "—", "note": "IE path", "price": "$15", "links": [], "only": ["ie"]}, {"tier": "aftermarket", "name": "Turbo inlet pipe (optional companion)", "pn": "IE IEINCI10 · 034-108-5011", "note": "Same afternoon", "price": "$150–250", "links": []}], "aftermarket": [{"name": "Integrated Engineering V2 cold air intake", "note": "Heat shield in two pieces, 5\" cone, cast inlet pipe, couplers for stock or IE inlet, coolant reroute, SAI adapter. Optional carbon lid. The most complete PDF.", "price": "$400–500 (+$200 CF lid)", "signal": "Best documented", "links": [{"store": "IE install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MQB%20CAI%20Install%20Guide%20IEINCI11_IEINCI12.pdf"}]}, {"name": "034Motorsport X34 (carbon) / P34 (plastic)", "note": "Replaces the upper box and inlet on the factory lower box; baffle removed; SAI provision; 2.75\" coupler. Torques in the PDF.", "price": "$300 (P34) – $700 (X34)", "signal": "Least invasive", "links": [{"store": "034 X34 install guide (PDF)", "url": "https://www.034motorsport.com/docs/034-108-1005-034motorsport-mqb-audi-volkswagen-gen3-18t-20t-a3-s3-tt-gti-golf-r-carbon-fiber-air-intake-install-instructions-diy-guide.pdf"}]}, {"name": "CTS Turbo IT-270", "note": "Full-replacement kit with heat shield; sheet hosted by ECS.", "price": "$350–450", "signal": "Tuner pick", "links": [{"store": "CTS install guide (PDF)", "url": "https://assets.ecstuning.com/edoc/CTS-IT-270R-V2.3.pdf"}]}, {"name": "Racingline R600 / APR / Unitronic / Eventuri", "note": "Full kits; R600 and APR built around larger MAF housings and their tunes; Eventuri is carbon and priced like it.", "price": "$500–1,200", "signal": "Tune-matched / premium", "links": []}], "tools": [{"name": "T25 Torx, 7mm socket, flat and Phillips screwdrivers, hose-clamp pliers"}, {"name": "4mm allen (shield bolts, SAI fitting); 2.5mm for IE's carbon lid", "only": ["ie", "o34", "cts", "other"]}, {"name": "Rags and a small pan; the kit's two silicone caps at hand", "only": ["ie"]}], "before": ["Engine completely cold (the IE path opens the cooling system).", "Lay the kit out against its list; identify which coupler is for a stock inlet vs an aftermarket inlet pipe.", "Don't force the airbox's plastic grommet brackets; they break."], "steps": [{"n": 1, "title": "Cover and hose", "blocks": [{"t": "text", "b": "Engine cover up at the corners. Intake hose: pliers on the airbox-side clamp, screwdriver on the turbo-side clamp, hose out. SAI: pinch the lock ring and pull it off the airbox. Vacuum line off the box gently; it's reused."}]}, {"n": 2, "title": "Front inlet and airbox out", "blocks": [{"t": "text", "b": "Coolant line out of its clips (lift). Two T25s on the sides of the front inlet, push the inlet down and lift each lock tab, inlet out of the radiator support. Lift the two rubber grommet brackets and the whole airbox comes up.", "only": ["ie", "cts", "other"]}, {"t": "text", "b": "Eight T25s on the lid (keep six for the 034 upper). Breather hose off the box, 7mm clamp at the turbo, lift the upper box and inlet. Panel filter out. Now the baffle inside the lower box: tight, wiggle it out; it's not reused.", "only": ["o34"]}, {"t": "ill", "id": "intake-mk7-hero", "cap": "Full kits replace the whole box; 034 keeps the lower half on its two grommet posts."}]}, {"n": 3, "title": "Coolant line reroute", "only": ["ie"], "caution": true, "blocks": [{"t": "text", "b": "Release the clamp on the factory coolant line, pull the hose back and cap the line immediately with the silicone cap; same on the lower return. Fit IE's silicone hose to the hard line and the radiator barb, one end at a time, quickly. Tighten both clamps."}, {"t": "warn", "b": "Cold engine only. Some coolant loss is normal; a pressurised system here is a burn."}]}, {"n": 4, "title": "Shield / upper in", "blocks": [{"t": "text", "b": "Bolt shield B to A (4 M6 button heads, 4mm allen). Shield under the radiator support, IE's grommets onto the two factory posts, one button head to the passenger radiator support. Rotate the SAI fitting 90° clockwise on its line.", "only": ["ie"]}, {"t": "text", "b": "Mount the SAI provision on the side of the box with the supplied fitting and allen bolt (4 Nm), or the block-off on an R/S3. 034 upper onto the lower box with the six saved T25s.", "only": ["o34"]}, {"t": "torque", "label": "Airbox lid screws (T25)", "nm": 4, "c": {"level": "high", "n": 1, "note": "4 Nm (034 PDF)."}, "only": ["o34"]}, {"t": "text", "b": "Heat shield onto the factory posts and any bracket per the sheet.", "only": ["cts", "other"]}]}, {"n": 5, "title": "Couplers, pipe, SAI, vacuum", "blocks": [{"t": "text", "b": "Two big clamps loose on the short silicone; SAI adapter (or plug) in it, clamp tight; vacuum fitting in. Pick the long coupler for your inlet (stock vs aftermarket TIP), clamps loose, pipe into it, orient to the turbo and the shield. SAI fitting onto the adapter until it clicks; factory vacuum line onto the barb."}]}, {"n": 6, "title": "Relaxed, then tight; filter", "caution": true, "blocks": [{"t": "text", "b": "Seat both couplers fully (turbo inlet and shield). Everything sitting with no tension? Now tighten all clamps."}, {"t": "torque", "label": "Coupler clamp at the turbo inlet", "nm": 5, "c": {"level": "high", "n": 1, "note": "5 Nm (034 TIP guide); IE says 'firmly'."}, "only": ["o34", "ie", "cts", "other"]}, {"t": "text", "b": "Filter onto the velocity stack, clamp. Trim seal around the shield edge (or the carbon lid: loosen the passenger mount bolt, ease the lid in, six M4s started at opposite ends, then everything tight)."}, {"t": "warn", "b": "A coupler clamped under tension walks off the turbo inlet under boost. Relaxed first, tight second."}]}, {"n": 7, "title": "Cover, coolant, start", "blocks": [{"t": "text", "b": "Engine cover on. IE path: check the coolant level and top up. Start it, listen at the couplers, look at the coolant joints. A minute of odd idle is adaptation."}]}], "alsoReplace": [{"name": "Turbo inlet pipe", "why": "The next restriction; IE and 034 sell them and the intake kit ships the matching coupler. IE's needs coil 1 out (10mm stud); 034's M8 bolt is 9 Nm."}, {"name": "PCV / air-oil separator", "why": "Right there with the airbox out; if it's original, do it."}, {"name": "Stage 1 tune", "why": "The intake's gain is mostly unlocked by software."}], "check": {"tab": "Which kit?", "title": "Which kit fits you?", "illId": "intake-mk7-hero", "illCap": "Invasiveness vs. completeness.", "rows": [{"see": "Want it least invasive, factory look", "means": "Upper-box replacement.", "do": "034 P34 (plastic) or X34 (carbon)."}, {"see": "Want the full kit with a real heat shield", "means": "Full replacement.", "do": "IE V2; add the carbon lid if you like."}, {"see": "IS38 planned", "means": "Intake plus inlet pipe.", "do": "IE V2 + IE TIP, or 034 X34 + 034 TIP."}, {"see": "Racingline/APR tune already", "means": "Tune-matched kit.", "do": "R600 or APR per your tuner."}], "c": {"level": "community", "n": 3, "note": "Kit documentation and owner threads."}}, "aftercare": ["Clamps after a week.", "IE: coolant level after the first two drives."], "disagreements": [{"topic": "Power?", "pos": "Vendors: modest gains on stock, more with a tune.", "call": "Sound on stock; real with a tune or IS38."}, {"topic": "Full kit or upper-box?", "pos": "034's approach keeps factory ducting; full kits add shielding.", "call": "Both work. Pick by how much you want to change."}], "sources": ["Integrated Engineering MK7/MQB Cold Air Intake V2 install guide", "034Motorsport X34 and P34 install guides; 034 turbo inlet guide (torques)", "CTS Turbo IT-270 install guide", "IE turbo inlet pipe guide (coil 1 removal)", "FCP Euro Gen 3 engine guide"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
